#!/usr/bin/env bash
# 仅开发态 mock，非 yiti_test、非真实后端联调。
# 用法：在已通过 playwright-cli 打开同名 session 后执行：
#   bash ROUND3-development-mock-routes.sh screen-round3-proof
set -euo pipefail

session="${1:-screen-round3-proof}"
pc() { npx playwright-cli "-s=${session}" "$@"; }

pc route '**/favicon.svg' --status 200 --content-type image/svg+xml --body '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"/>'
pc route '**/api/auth/current-user' --status 200 --content-type application/json --body '{"code":"0","message":"success","traceId":"round3-proof-auth-current","data":{"empId":"u-round3-proof","username":"u-round3-proof","displayName":"开发态 Mock 管理员","mainOrgCode":"ORG_001","mainOrgName":"西安管理行","roles":[{"roleId":"9001","roleCode":"SYS_ADMIN","roleChName":"系统管理员"}],"isSystemAdmin":true}}'
pc route '**/api/auth/my-menus' --status 200 --content-type application/json --body '{"code":"0","message":"success","traceId":"round3-proof-menus","data":[{"resourceId":"M_REPORT","resourceUrl":"/report","menuName":"报表分析","children":[{"resourceId":"M_SCREEN_DS","resourceUrl":"/screen-admin/datasources","menuName":"大屏数据源"},{"resourceId":"M_SCREEN_DESIGN","resourceUrl":"/screen-admin/designer","menuName":"大屏设计器"}]}]}'
pc route '**/api/auth/permissions' --status 200 --content-type application/json --body '{"code":"0","message":"success","traceId":"round3-proof-permissions","data":{"resourceUrls":["/api/screen/admin/screens","/api/screen/admin/canvas/101","/api/screen/admin/canvas/save","/api/screen/admin/canvas/publish","/api/screen/admin/canvas/rollback","/api/screen/admin/canvas/101/publish-logs","/api/screen/admin/screens/101/metadata","/api/screen/admin/screens/101/access-roles","/api/screen/admin/datasources","/api/admin/org-groups","/api/admin/org-profiles","/api/admin/roles/all"],"roleCodes":["SYS_ADMIN"],"isSystemAdmin":true}}'
