pc route '**/api/screen/admin/canvas/publish' --status 200 --content-type application/json --body '{"code":"0","message":"success","traceId":"round3-proof-publish","data":null}'
pc route '**/api/screen/admin/canvas/rollback' --status 200 --content-type application/json --body '{"code":"0","message":"success","traceId":"round3-proof-rollback","data":null}'
